/* @lc app=leetcode id=2961 lang=kotlin */ class Solution { fun getGoodIndices(variables: Array<IntArray>, target: Int): List<Int> = variables.indices.filter { i -> variables[i].let { v -> java.math.BigInteger.valueOf(v[0].toLong()).modPow(java.math.BigInteger.valueOf(v[1].toLong()), java.math.BigInteger.TEN).modPow(java.math.BigInteger.valueOf(v[2].toLong()), java.math.BigInteger.valueOf(v[3].toLong())).toInt() == target } } }